<style>
body{margin:0;background:#eef0ec;font-family:Poppins,system-ui,sans-serif;color:#2b2b2b}
.wrap{max-width:1280px;margin:0 auto;padding:18px 16px}
h1{font-size:1.15rem;margin:6px 0 12px}.back{color:#037A3B;text-decoration:none;font-size:.85rem}
.grid{display:grid;grid-template-columns:minmax(280px,380px) 1fr;gap:14px}@media(max-width:900px){.grid{grid-template-columns:1fr}}
.panel{background:#fff;border-radius:12px;padding:14px;box-shadow:0 2px 8px rgba(0,0,0,.05)}
.locked{background:#E3F3EA;border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:.82rem}.locked div{display:flex;justify-content:space-between;gap:8px}.locked span{color:#555}.locked small{color:#037A3B}
.lbl{display:block;font-weight:600;font-size:.88rem;margin:10px 0 4px}
textarea{width:100%;box-sizing:border-box;font:inherit;font-size:.9rem;border:1px solid #cfd4cb;border-radius:8px;padding:8px 10px;resize:vertical}
.meta{display:flex;justify-content:space-between;gap:8px;font-size:.75rem;color:#6b7067;margin-top:3px}
.count{font-weight:600;color:#037A3B;white-space:nowrap}.count.amber{color:#b45309}.count.full{color:#b42318}
.bar{display:flex;gap:8px;align-items:center;margin-top:14px}.dirty{color:#b45309;font-size:.8rem;margin-right:auto}
.btn{background:#048C44;color:#fff;border:0;border-radius:8px;padding:8px 16px;font:inherit;font-weight:600;cursor:pointer}.btn.o{background:#fff;color:#037A3B;border:1px solid #048C44}
.alert{border-radius:8px;padding:10px 12px;margin-bottom:12px;font-size:.88rem}.alert.success{background:#E3F3EA}.alert.danger{background:#fde8e8}.alert.info{background:#fff7e6}
.pv{overflow:hidden;background:#e9ece7;border-radius:8px;margin-top:6px}#pv{width:1123px;height:794px;border:0;transform-origin:0 0;background:#fff}
.small{font-size:.78rem;color:#6b7067}code{background:#f1f3ef;padding:0 3px;border-radius:3px}
</style>
